CREATE TABLE `deep_rows` (
  `id` int NOT NULL,
  `v0` varchar(63) NOT NULL,
  `v1` varchar(63) NOT NULL,
  `v2` varchar(63) NOT NULL,
  `v3` varchar(63) NOT NULL,
  `v4` varchar(63) NOT NULL,
  `v5` varchar(63) NOT NULL,
  `v6` varchar(63) NOT NULL,
  `v7` varchar(63) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;
